    # ─────────────────────────────────────────
    # chat.request — 对话请求
    # ─────────────────────────────────────────
    async def _handle_chat_request(self, payload):
        task_id = payload.get('task_id') or 'task-%s' % uuid.uuid4().hex[:8]
        message = payload.get('message', '')
        sender = payload.get('sender')

        # 接单模式拒绝新的对话请求
        if getattr(self.app, 'run_mode', 'local') == 'order':
            logger.info('[接单模式] 拒绝对话请求: task=%s', task_id)
            await self.ws.send(protocol.make_chat_reply(
                task_id, '[接单模式] 当前不接受对话请求，仅处理平台委派的项目任务。'))
            await self.ws.send(protocol.make_chat_done(task_id))
            return

        if not message:
            logger.warning('chat.request 缺少 message 字段')
            return

        t_start = time.monotonic()
        logger.info('[计时] Handler 收到对话请求: task=%s msg=%s',
                    task_id, message[:100])

        # 发送任务开始
        await self.ws.send(protocol.make_task_update(
            task_id, 'running', progress=0.0))

        # 流式执行对话流水线，通过 asyncio.Queue 桥接同步生成器与异步 WS
        full_reply = ''
        chunk_count = 0
        t_first_chunk = None
        queue = asyncio.Queue()
        loop = asyncio.get_event_loop()

        def _run_stream():
            try:
                for chunk in self.app.process_message_stream(message, sender):
                    # chunk 可能是 (kind, data) 元组或纯字符串
                    if isinstance(chunk, tuple):
                        loop.call_soon_threadsafe(queue.put_nowait, ('chunk', chunk))
                    else:
                        loop.call_soon_threadsafe(queue.put_nowait, ('chunk', ('content', chunk)))
            except Exception as e:
                logger.exception('流式对话异常')
                loop.call_soon_threadsafe(queue.put_nowait, ('error', str(e)))
            finally:
                loop.call_soon_threadsafe(queue.put_nowait, ('done', None))

        loop.run_in_executor(None, _run_stream)

        # 从队列读取并发送 WS 流式消息
        while True:
            msg_type, data = await queue.get()
            if msg_type == 'chunk':
                if t_first_chunk is None:
                    t_first_chunk = time.monotonic()
                    logger.info('[计时] Handler 首chunk到达: task=%s LLM首token耗时 %.1fms',
                                task_id, (t_first_chunk - t_start) * 1000)
                chunk_count += 1
                # data 是 (kind, text) 元组
                kind, text = data
                if kind == 'content':
                    full_reply += text
                    await self.ws.send(protocol.make_chat_stream(task_id, text))
                # reasoning / tool_call 等类型仅记录不转发
            elif msg_type == 'error':
                await self.ws.send(protocol.make_chat_reply(
                    task_id, '处理失败: %s' % data))
                break
            elif msg_type == 'done':
                break

        t_end = time.monotonic()
        logger.info('[计时] Handler 流式完成: task=%s chunks=%d reply_len=%d '
                    'LLM总耗时=%.1fms 首token=%.1fms WS发送=%.1fms',
                    task_id, chunk_count, len(full_reply),
                    (t_end - t_start) * 1000,
                    (t_first_chunk - t_start) * 1000 if t_first_chunk else 0,
                    (t_end - (t_first_chunk or t_end)) * 1000)

        # 发送完整回复 + 完成信号
        await self.ws.send(protocol.make_chat_reply(task_id, full_reply))
        await self.ws.send(protocol.make_chat_done(task_id))
        await self.ws.send(protocol.make_task_update(
            task_id, 'done', progress=1.0))

    # ─────────────────────────────────────────
    # command — 管理命令
    # ─────────────────────────────────────────
    async def _handle_command(self, payload):
        command_str = payload.get('command', '')
        if not command_str:
            logger.warning('command 消息缺少 command 字段')
            return

        logger.info('收到管理命令: %s', command_str)
        loop = asyncio.get_event_loop()
        try:
            result = await loop.run_in_executor(
                None, self.app.commands.execute, command_str, self.app)
        except Exception as e:
            result = {'success': False, 'error': str(e)}
            logger.exception('命令执行异常: %s', command_str)

        # 命令结果通过日志上报
        await self.ws.send(protocol.make_log(
            self.app.config.agent_id, 'info',
            '命令执行完成: %s' % command_str,
            result=result))

    # ─────────────────────────────────────────
    # config.update — 配置热更新
    # ─────────────────────────────────────────
    async def _handle_config_update(self, payload):
        new_config = payload.get('config', {})
        if not new_config:
            return

        logger.info('收到配置更新: %s', list(new_config.keys()))

        # ★ 特殊处理: runtime_mode 需要完整的模式切换流程（WS 连接管理）
        if 'runtime_mode' in new_config:
            new_mode = new_config['runtime_mode']
            if new_mode in ('local', 'collaborative', 'order'):
                old_mode = self.app.config.run_mode
                if old_mode != new_mode:
                    logger.info('平台下发模式切换: %s → %s', old_mode, new_mode)
                    self.app.config.run_mode = new_mode
                    self.app.run_mode = new_mode
                    # 复用 mode.py 的模式变更逻辑（保持连接 + 立即上报）
                    from agent_runtime.server.api.mode import (
                        apply_mode_change)
                    await apply_mode_change(self.app, new_mode)
                    # 模式不持久化到文件，仅通过心跳上报到平台 DB
                    logger.info('模式切换完成: %s → %s', old_mode, new_mode)
                    return  # 已完成模式切换，不再处理其他 updatable

        # 更新可热更新的参数
        updatable = {
            'max_history', 'max_tool_rounds', 'llm_timeout',
            'tool_timeout', 'output_limit', 'token_monthly_cap',
            'token_warning_threshold', 'heartbeat_interval',
            'skill_confidence_threshold',
        }
        for key, val in new_config.items():
            if key in updatable:
                self.app.config.params[key] = val
                logger.info('配置已热更新: %s = %s', key, val)

    # ─────────────────────────────────────────
    # a2a.invoke — 跨 Agent 调用
    # ─────────────────────────────────────────
    async def _handle_a2a_invoke(self, payload):
        task_id = payload.get('task_id') or 'task-%s' % uuid.uuid4().hex[:8]
        target_agent = payload.get('target_agent', '')
        message = payload.get('message', '')

        if not message:
            logger.warning('a2a.invoke 缺少 message 字段')
            return

        logger.info('收到 A2A 调用: target=%s msg=%s',
                    target_agent, message[:100])

        # 本地 A2A 调用走同一 process_message 流水线
        loop = asyncio.get_event_loop()
        try:
            reply = await loop.run_in_executor(
                None, self.app.process_message, message,
                target_agent or None)
        except Exception as e:
            logger.exception('A2A 调用处理异常')
            reply = 'A2A 处理失败: %s' % e

        await self.ws.send(protocol.make_chat_reply(task_id, reply))
        await self.ws.send(protocol.make_chat_done(task_id))

    # ─────────────────────────────────────────
    # platform.task.assign — 平台委派任务
    # ─────────────────────────────────────────
    async def _handle_platform_task_assign(self, payload):
        """处理平台委派任务消息。

        v2.0: 使用 TaskContext + TaskZeroExecutor/TaskExecutor 执行流水线。
        支持 Task 0 拆解（队长角色）和常规任务执行（队员角色）。
        """
        from agent_runtime.core.task_engine import TaskEngine
        from agent_runtime.core.task_executor import TaskContext

        # 防御性检查：本地模式不应收到平台任务
        if getattr(self.app, 'run_mode', 'local') == 'local':
            logger.warning('本地模式收到平台任务委派，忽略')
            return

        platform_task_id = payload.get('platform_task_id')
        task_id = payload.get('task_id', '')
        title = payload.get('title', '')

        if not platform_task_id:
            logger.warning('platform.task.assign 缺少 platform_task_id')
            return

        logger.info('收到平台任务委派: platform_id=%s task_id=%s title=%s',
                    platform_task_id, task_id, title[:100])

        loop = asyncio.get_event_loop()

        # 构造 TaskContext（完整 spec_document，不再截断）
        ctx = TaskContext.from_payload(payload, self.app.config.home)
        ctx.ensure_dirs()

        # 如果携带 repo_url，在任务执行前先 clone 仓库（同步，确保代码就绪）
        repo_url = payload.get('repo_url') or ''
        if repo_url and ctx.project_id:
            logger.info('任务委派携带 repo_url，先 clone 仓库: %s', repo_url)
            try:
                from agent_runtime.core.project_engine import ProjectEngine
                pe = ProjectEngine(db=self.app.db)
                await loop.run_in_executor(
                    None, pe.clone_repo, ctx.project_id, repo_url, 'main')
            except Exception:
                logger.exception('clone 仓库失败（任务将继续执行）: %s', repo_url)

        # 进度回调：通过 WS 上报到平台
        def _progress_cb(progress, phase, message):
            asyncio.run_coroutine_threadsafe(
                self.ws.send(protocol.make_agent_task_progress(
                    platform_task_id, progress,
                    message=message, phase=phase)),
                loop)
        ctx.progress_callback = _progress_cb

        # 创建本地任务记录
        engine = TaskEngine(
            db=self.app.db,
            ws_client=self.ws,
            agent_id=self.app.config.agent_id)

        local_message = title
        if ctx.spec_document:
            local_message = '%s\n\n[任务规格]\n%s' % (
                title, ctx.spec_document[:2000])

        task = await loop.run_in_executor(
            None, engine.create_task,
            local_message, 'project', ctx.priority, None, 3,
            None, platform_task_id, task_id, ctx.project_id)

        if not task:
            logger.warning('任务创建失败: platform_id=%s', platform_task_id)
            return

        # 启动任务
        started = await loop.run_in_executor(
            None, engine.start_task, task['id'])
        if not started:
            logger.warning('平台任务启动失败: local_id=%s', task['id'])
            return

        logger.info('平台任务已启动: local_id=%s platform_id=%s '
                    'is_task_zero=%s type=%s workspace=%s',
                    task['id'], platform_task_id,
                    ctx.is_task_zero, ctx.task_type, ctx.task_workspace)

        # 在线程池中执行任务（避免阻塞异步事件循环）
        def _execute_task():
            self.app._current_task_context = ctx
            try:
                result = self.app.execute_platform_task(ctx)

                # 更新本地任务状态
                engine.complete_task(
                    task['id'],
                    result=result.result_document,
                    token_used=result.token_used)
                engine.db.update_task(task['id'], progress=100)

                logger.info('平台任务执行完成: local_id=%s status=%s '
                            'token=%d artifacts=%d',
                            task['id'], result.result_status,
                            result.token_used, len(result.artifacts))

                # 向平台提交结果
                asyncio.run_coroutine_threadsafe(
                    self.ws.send(protocol.make_agent_task_result(
                        platform_task_id,
                        result_document=result.result_document or '',
                        result_status=result.result_status,
                        token_used=result.token_used)),
                    loop)

            except Exception as e:
                logger.exception('平台任务执行异常: local_id=%s',
                                 task['id'])
                engine.fail_task(
                    task['id'], error_type='unknown',
                    error_message=str(e)[:500])
                # 向平台上报阻塞/失败
                asyncio.run_coroutine_threadsafe(
                    self.ws.send(protocol.make_agent_task_blocked(
                        platform_task_id,
                        reason=str(e)[:200])),
                    loop)
            finally:
                self.app._current_task_context = None

        loop.run_in_executor(None, _execute_task)

    # ─────────────────────────────────────────
    # platform.task.cancel — 平台取消任务
    # ─────────────────────────────────────────
    async def _handle_platform_task_cancel(self, payload):
        """处理平台取消任务消息。"""
        from agent_runtime.core.task_engine import TaskEngine

        platform_task_id = payload.get('platform_task_id')
        reason = payload.get('reason', '')

        if not platform_task_id:
            logger.warning('platform.task.cancel 缺少 platform_task_id')
            return

        logger.info('收到平台任务取消: platform_id=%s reason=%s',
                    platform_task_id, reason)

        loop = asyncio.get_event_loop()
        engine = TaskEngine(
            db=self.app.db,
            ws_client=self.ws,
            agent_id=self.app.config.agent_id)

        # 查找本地任务
        tasks = await loop.run_in_executor(
            None, engine.list_tasks, 720, 500, 'project')
        local_task = None
        for t in tasks:
            if t.get('platform_task_id') == platform_task_id:
                local_task = t
                break

        if local_task:
            await loop.run_in_executor(
                None, engine.cancel_task, local_task['id'],
                reason or '平台取消')
            logger.info('平台任务已取消: local_id=%s', local_task['id'])
        else:
            logger.warning('未找到对应的本地任务: platform_id=%s',
                          platform_task_id)

    # ─────────────────────────────────────────
    # ping — 平台侧心跳探测
    # ─────────────────────────────────────────
    async def _handle_ping(self, payload):
        pong = {'type': 'pong',
                'ts': __import__('time').time(),
                'agent_id': self.app.config.agent_id}
        await self.ws.send(pong)
